/**
 * Value-reference codec for the automation tf dialect.
 *
 * The compose wire carries refs as JSON envelopes ({triggerReference},
 * {taskReference}, {variableReference}, {templateReference}, {value}); ei's
 * HCL dialect carries them as `refs["…"]` RESOURCE EXPRESSIONS resolved at
 * apply — `elementum_on_demand_trigger.x.refs["STUDENT_NAME"]` — with plain
 * literals for static values and `${…}` interpolated strings for multi-part
 * templates (cmd/elementum/export/hcl_task.go convertToRefsSyntax). ei's
 * exporter falls back to embedding the raw JSON (with platform ids) when it
 * can't resolve a ref; that fallback is NOT reproduced here — build emits only
 * the id-free refs syntax, and pull reports the JSON fallback loudly instead
 * of guessing.
 *
 * refs-map KEY naming (provider sources):
 *  - on_demand trigger: the DECLARED parameter name (the authored schema key;
 *    the wire's triggerReference name is the Mobius-canonicalized form —
 *    reverse-mapped here via the declared names).
 *  - variable task: the variable_name (buildVariableTaskRefs).
 *  - execute_script: "Result" for the whole result, "result.<prop>" per
 *    output-schema property.
 */
import { normalizeOnDemandParamKey } from "../../../pull/util.js";
import { expr, isTfExpr, sanitizeName } from "../../engine/tf/index.js";
import { AUTOMATION_SUB_TYPE_BY_RESOURCE, AUTOMATION_SUB_TYPE_BY_TYPE_KEY } from "./types.js";
const VARIABLE_TASK_TYPE = AUTOMATION_SUB_TYPE_BY_TYPE_KEY.get("variable").resourceType;
/** Map an authored/canonical onDemand param key to the declared parameter name. */
export function onDemandTriggerRefKey(name, paramNames) {
    if (paramNames.includes(name))
        return name;
    return paramNames.find((p) => normalizeOnDemandParamKey(p) === name) ?? name;
}
function refsExpr(type, label, key) {
    return expr.resourceAttr(type, label, ["refs", { index: key }]);
}
/** Wire ref envelope → tf attribute value (literal, refs expression, or template). */
export function wireRefToTf(ref, ctx) {
    if (ref === null || typeof ref !== "object") {
        return typeof ref === "string" || typeof ref === "number" || typeof ref === "boolean"
            ? { value: ref }
            : { unsupported: `unrecognized value shape ${JSON.stringify(ref)}` };
    }
    const r = ref;
    if ("value" in r && Object.keys(r).length === 1) {
        const v = r["value"];
        if (typeof v === "string" || typeof v === "number" || typeof v === "boolean")
            return { value: v };
        return { unsupported: `static value of unsupported type ${JSON.stringify(v)}` };
    }
    const trig = r["triggerReference"];
    if (trig !== undefined && typeof trig?.name === "string") {
        // The wire carries the AUTHORED name verbatim (canonicalization dropped);
        // exact declared match wins. The canonical-form lookup remains only for
        // sources printed by the old printer, whose access paths were camelCased.
        return { value: refsExpr(ctx.triggerType, ctx.autoLabel, onDemandTriggerRefKey(trig.name, ctx.paramNames)) };
    }
    const task = r["taskReference"];
    if (task !== undefined && typeof task?.name === "string") {
        const refKey = task.taskRefKey ?? "";
        const type = ctx.taskType(refKey);
        if (type === undefined)
            return { unsupported: `taskReference to unknown/uncarried task "${refKey}"` };
        const key = task.name === "result" ? "Result" : task.name;
        if (key !== "Result" && !key.startsWith("result.")) {
            return { unsupported: `taskReference output "${task.name}" has no known refs-map key` };
        }
        if (key.startsWith("result.")) {
            // Per-property result refs exist ONLY when the script declares that
            // property in its output schema — otherwise the apply fails with
            // "Invalid index" on the refs map. Fail at build instead, with the fix.
            const prop = key.slice("result.".length);
            if (!ctx.taskResultProps(refKey).includes(prop)) {
                return {
                    unsupported: `references result.${prop} of task "${refKey}", but that task declares no output schema for it — ` +
                        `add outputs: { ${prop}: "text" } (or the right type) to its executeScript`,
                };
            }
        }
        return { value: refsExpr(type, `${ctx.autoLabel}_${sanitizeName(refKey)}`, key) };
    }
    const variable = r["variableReference"];
    if (variable !== undefined && typeof variable?.id === "string") {
        const target = ctx.variableById.get(variable.id);
        if (target === undefined)
            return { unsupported: `variableReference to an id not created in this workflow` };
        return {
            value: refsExpr(VARIABLE_TASK_TYPE, `${ctx.autoLabel}_${sanitizeName(target.taskRefKey)}`, target.varName),
        };
    }
    const template = r["templateReference"];
    if (template !== undefined && typeof template?.template === "string") {
        const params = template.parameters ?? [];
        // Single bare placeholder collapses to the ref itself (matches ei).
        if (template.template === "{{{p1}}}" && params.length === 1) {
            return wireRefToTf(params[0]?.value?.value, ctx);
        }
        const byName = new Map();
        for (const p of params) {
            if (typeof p?.value?.name === "string")
                byName.set(p.value.name, p.value.value);
        }
        const parts = [];
        let rest = template.template;
        const placeholder = /\{\{\{(\w+)\}\}\}/;
        for (;;) {
            const m = placeholder.exec(rest);
            if (m === null)
                break;
            if (m.index > 0)
                parts.push(rest.slice(0, m.index));
            const inner = wireRefToTf(byName.get(m[1]), ctx);
            if ("unsupported" in inner)
                return inner;
            if (isTfExpr(inner.value))
                parts.push(inner.value);
            else
                parts.push(String(inner.value));
            rest = rest.slice(m.index + m[0].length);
        }
        if (rest !== "")
            parts.push(rest);
        return { value: { $expr: "template", parts } };
    }
    return { unsupported: `unsupported reference kind: ${Object.keys(r).join(", ")}` };
}
/** Index the stamped variable ids in a finalized payload: id → {taskRefKey, varName}. */
export function indexVariableIds(tasks) {
    const index = new Map();
    for (const t of tasks) {
        const variable = t.task?.["variable"];
        for (const c of variable?.create ?? []) {
            if (typeof c?.id === "string" && typeof c?.name === "string" && typeof t.refKey === "string") {
                index.set(c.id, { taskRefKey: t.refKey, varName: c.name });
            }
        }
    }
    return index;
}
function refKeyFromLabel(label, autoLabel) {
    return label.startsWith(`${autoLabel}_`) ? label.slice(autoLabel.length + 1) : label;
}
/** tf attribute value → printer AST node (inverse of wireRefToTf). */
export function tfRefToAst(value, ctx) {
    if (typeof value === "string" || typeof value === "number" || typeof value === "boolean") {
        // A raw JSON envelope means ei fell back past refs syntax (unresolvable
        // ref at export time) — report rather than round-trip platform ids.
        if (typeof value === "string" && value.startsWith('{"')) {
            return { unsupported: "ei exported a raw JSON value reference (refs-syntax fallback); not round-tripped" };
        }
        return { ast: value };
    }
    if (!isTfExpr(value))
        return { unsupported: `unrecognized tf value ${JSON.stringify(value)}` };
    if (value.$expr === "template") {
        const parts = [];
        for (const part of value.parts) {
            if (typeof part === "string") {
                parts.push(part);
                continue;
            }
            const inner = tfRefToAst(part, ctx);
            if ("unsupported" in inner)
                return inner;
            if (typeof inner.ast === "object")
                parts.push(inner.ast);
            else
                parts.push(String(inner.ast));
        }
        return { ast: { kind: "template", parts } };
    }
    if (value.$expr === "resource-attr" && value.path.length === 2 && value.path[0] === "refs") {
        const seg = value.path[1];
        const key = typeof seg === "object" ? seg.index : String(seg);
        const type = value.type;
        if (ctx.isTriggerType(type)) {
            // The refs key IS the declared parameter name — print it verbatim; the
            // printer emits bracket access when it isn't identifier-safe.
            return { ast: { kind: "triggerRef", path: [key] } };
        }
        const refKeyOf = (label) => ctx.refKeyByLabel.get(label) ?? refKeyFromLabel(label, ctx.autoLabel);
        if (type === VARIABLE_TASK_TYPE) {
            return {
                ast: { kind: "variableParamRef", varTask: refKeyOf(value.label), name: key },
            };
        }
        if (AUTOMATION_SUB_TYPE_BY_RESOURCE.has(type)) {
            const path = key === "Result" ? ["result"] : key.split(".");
            return { ast: { kind: "taskRef", task: refKeyOf(value.label), path } };
        }
        return { unsupported: `refs expression on unrecognized resource type ${type}` };
    }
    return { unsupported: `unsupported tf expression ${JSON.stringify(value).slice(0, 120)}` };
}
